/* Rentcam promo schedule runtime v7 — scoped and lightweight */
(function(){
  if(location.pathname.startsWith('/cms'))return;
  const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Math.max(0,Number(n)||0));
  const cfg=()=>window.RENTCAM_CMS_CONFIG||null;
  const dayStart=s=>s?new Date(s+'T00:00:00').getTime():null;
  const dayEnd=s=>s?new Date(s+'T23:59:59').getTime():null;
  const inRange=(a,b)=>{const n=Date.now(),x=dayStart(a),y=dayEnd(b);return(!x||n>=x)&&(!y||n<=y)};
  function meta(id){const c=cfg();if(!c)return null;return(c.customProducts||[]).find(x=>String(x.id)===String(id))||(c.productOverrides||{})[id]||null}
  const visible=x=>!x||((x.active!==false)&&(x.deleted!==true)&&inRange(x.publishDate,x.unpublishDate));
  const labelOn=x=>!!x?.labelText&&inRange(x.labelStart,x.labelEnd);
  const discountOn=x=>Number(x?.discountPercent)>0&&inRange(x.discountStart,x.discountEnd);
  function idFromCard(card){let id=card.getAttribute('data-product-id')||card.dataset?.productId||'';if(!id){const m=(card.getAttribute('onclick')||'').match(/\/produk\/([^'\")]+)/);if(m)id=m[1]}return decodeURIComponent(id||'')}
  function style(){if(document.getElementById('v7promo'))return;const s=document.createElement('style');s.id='v7promo';s.textContent=`.v7-product-label{position:absolute;z-index:5;left:10px;top:10px;background:#111;color:#fff;padding:7px 10px;border-radius:999px;font-size:10px;font-weight:900}.v7-discount-label{background:#f26a21}.v7-old-price{text-decoration:line-through;color:#929292;font-weight:600;margin-right:6px}.v7-new-price{color:#d84d0f;font-weight:900}.v7-detail-promo{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0 14px}.v7-detail-promo span{display:inline-flex;padding:7px 10px;border-radius:999px;font-size:11px;font-weight:900;background:#111;color:#fff}.v7-detail-promo span.sale{background:#f26a21}`;document.head.appendChild(s)}
  function parsePrice(el){const t=el?.textContent||'';const m=t.replace(/\./g,'').replace(/,/g,'').match(/(?:Rp\s*)?(\d{2,})/i);return m?Number(m[1]):0}
  function patchCard(card){const id=idFromCard(card);if(!id)return;const x=meta(id);if(!x)return;card.style.display=visible(x)?'':'none';if(!visible(x))return;const holder=card.querySelector('.pimg,.home-category-image')||card;holder.style.position='relative';let lab=holder.querySelector('.v7-product-label');if(labelOn(x)||discountOn(x)){if(!lab){lab=document.createElement('span');lab.className='v7-product-label';holder.appendChild(lab)}lab.textContent=labelOn(x)?x.labelText:(x.discountLabel||('DISKON '+Number(x.discountPercent)+'%'));lab.className='v7-product-label'+(discountOn(x)?' v7-discount-label':'')}else lab?.remove();const pr=card.querySelector('.price');if(pr){if(!pr.dataset.v7Original)pr.dataset.v7Original=pr.innerHTML;if(discountOn(x)){const base=Number(x.price)||parsePrice(pr);if(base){const cut=Math.round(base*(1-Number(x.discountPercent)/100));pr.innerHTML=`<span class="v7-old-price">${money(base)}</span><span class="v7-new-price">${money(cut)}</span> <small>/ full day</small>`}}else if(pr.dataset.v7Original)pr.innerHTML=pr.dataset.v7Original}}
  function patchCards(){document.querySelectorAll('#app .pcard,#app [data-product-id],#app .home-category-card').forEach(patchCard)}
  function currentId(){const m=location.pathname.match(/^\/produk\/([^/?#]+)/);return m?decodeURIComponent(m[1]):''}
  function patchDetail(){const id=currentId();if(!id)return;const x=meta(id);if(!x)return;const app=document.getElementById('app');if(!visible(x)){const root=app?.querySelector('.page')||app;if(root&&!root.dataset.v7Unavailable){root.dataset.v7Unavailable='1';root.innerHTML='<div class="container" style="padding:80px 0"><h1>Produk tidak tersedia</h1><p>Produk ini sedang dinonaktifkan atau berada di luar jadwal tampil.</p><button class="btn" onclick="go(\'/produk\')">Kembali ke Rentals</button></div>'}return}const h1=app?.querySelector('h1');if(h1){let box=h1.parentElement?.querySelector('.v7-detail-promo');if(!box){box=document.createElement('div');box.className='v7-detail-promo';h1.insertAdjacentElement('afterend',box)}box.innerHTML='';if(labelOn(x))box.insertAdjacentHTML('beforeend',`<span>${String(x.labelText).replace(/</g,'&lt;')}</span>`);if(discountOn(x))box.insertAdjacentHTML('beforeend',`<span class="sale">${String(x.discountLabel||('DISKON '+Number(x.discountPercent)+'%')).replace(/</g,'&lt;')}</span>`);if(!box.childElementCount)box.remove()}}
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;style();patchCards();patchDetail()})}
  const app=document.getElementById('app');if(app)new MutationObserver(run).observe(app,{childList:true,subtree:true});document.addEventListener('rentcam-cms-updated',run);document.addEventListener('rentcam-route-change',run);addEventListener('popstate',run);setTimeout(run,150);
})();